import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.BS0bAV7E.js";const _=JSON.parse('{"title":"版本号规则","description":"","frontmatter":{},"headers":[],"relativePath":"zh/release/versioning.md","filePath":"zh/release/versioning.md"}'),r={name:"zh/release/versioning.md"};function i(l,e,c,n,s,h){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="版本号规则" tabindex="-1">版本号规则 <a class="header-anchor" href="#版本号规则" aria-label="Permalink to &quot;版本号规则&quot;">​</a></h1><h2 id="版本方案" tabindex="-1">版本方案 <a class="header-anchor" href="#版本方案" aria-label="Permalink to &quot;版本方案&quot;">​</a></h2><p>自 v1.0.0 正式发布起，版本标识符采用 <strong>SemVer</strong>（语义化版本）： <code>1.0.0</code>、<code>1.1.0</code>... 在此之前的工程阶段使用工作包阶段名称 （<code>WP-14-docs_release</code>、<code>WP-13-build_system</code>...）- 即内部按功能集划分的发布线。</p><p>此外，每次构建还携带：</p><ul><li><strong>构建号</strong> = 构建时的提交计数（<code>git rev-list --count HEAD</code>）- 单调递增，发布于更新清单的 <code>build</code> 字段（横幅/uname 携带版本号）。</li><li><strong>版本横幅</strong> = Makefile 中固定的 <code>OC_RELEASE_VERSION ?= 1.0.0</code> 字面量（显式 <code>OC_RELEASE_VERSION=</code> 覆盖仍然优先，E2E 更新测试即依赖此机制）- 烘焙到内核横幅、uname、OTA 清单和 ISO 中。早期构建使用 <code>git describe --tags</code> 推导；v1.0.0 起固化为字面量，横幅不再依赖本地 git 状态。</li></ul><h2 id="各数字的含义" tabindex="-1">各数字的含义 <a class="header-anchor" href="#各数字的含义" aria-label="Permalink to &quot;各数字的含义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>位置</th><th>示例</th><th>含义</th></tr></thead><tbody><tr><td><code>uname -a</code></td><td><code>Open Cube OS 1.0.0 x86_64</code></td><td>运行中内核的版本</td></tr><tr><td>update.json</td><td><code>version: 1.0.0, build: 275</code></td><td>已发布的清单</td></tr><tr><td>发布标签</td><td><code>v1.0.0</code></td><td>资源所构建自的 git 标签</td></tr><tr><td>gh-pages</td><td>下载页面中的相同两个数字</td><td>网站镜像了发布版本</td></tr></tbody></table><p>一次发布 = 一个标签 = 一个构建号 = 一个清单 = 一组覆盖本地 / 发布版本 / gh-pages / 私有镜像的 SHA256。</p><h2 id="兼容性承诺" tabindex="-1">兼容性承诺 <a class="header-anchor" href="#兼容性承诺" aria-label="Permalink to &quot;兼容性承诺&quot;">​</a></h2><ul><li>Shell 命令永不删除；增加是常态（基线上移：176 -&gt; 192 -&gt; ... -&gt; 233）。</li><li>L1 编号接口永不重新编号；新组追加。</li><li>OTA 包仅更新内核；/etc 卷内容向前携带。</li><li>自本版起遵循 SemVer：破坏性变更升 MAJOR，新增命令或 L1 组升 MINOR，修复升 PATCH。</li></ul><h2 id="选择下一个版本" tabindex="-1">选择下一个版本 <a class="header-anchor" href="#选择下一个版本" aria-label="Permalink to &quot;选择下一个版本&quot;">​</a></h2><p>按上文 SemVer 规则选取；<code>build</code> = 发布当天的提交计数 - 绝不手动挑选。</p>',12)])])}const g=t(r,[["render",i]]);export{_ as __pageData,g as default};
